function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // character
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // fixed mindset bubble
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 70, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('I\'m stuck', W/2, H/2 - 70);

  // locked chain
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 40);
  ctx.lineTo(W/2, H/2 - 10);
  ctx.stroke();
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W/2, H/2 - 30 + i * 10, 5, 0, 2 * Math.PI);
    ctx.stroke();
  }

  // "cannot change" text
  ctx.font = '25px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Cannot Change', W/2, H - 30 + 20 * Math.sin(t));

  ctx.restore();
}
